45	            `/${splat}`
46	          ).pipe(
47	            Effect.mapError(
48	              () =>
49	                new DocsSourceError({
50	                  message: "The docs page path was invalid.",
51	                  operation: "decode",
52	                })
53	            )
54	          );
55	          const navigation = yield* content.getNavigation();
56	          const page = yield* content.getPage(path);
57	          yield* preloadDocsContent(page.source);
58	
59	          return {
60	            navigation,
61	            page,
62	          };
63	        })
64	      ),
65	      Effect.catchTag("DocsPageNotFoundError", () => Effect.die(notFound())),
66	      docsPageRouteBoundary.encodeExit
67	    )
68	  );
 1	import { Context } from "effect";
 2	import type { Effect } from "effect";
 3	
 4	import type { DocsPageNotFoundError, DocsSourceError } from "./errors.js";
 5	import type {
 6	  DocsContentPage,
 7	  DocsNavigation,
 8	  DocsPagePath,
 9	  DocsValidationResult,
10	} from "./schemas.js";
11	
12	export interface DocsContentServiceContract {
13	  readonly getNavigation: () => Effect.Effect<DocsNavigation, DocsSourceError>;
14	  readonly getPage: (
15	    path: DocsPagePath
16	  ) => Effect.Effect<DocsContentPage, DocsPageNotFoundError | DocsSourceError>;
17	  readonly listPages: () => Effect.Effect<
18	    readonly DocsContentPage[],
19	    DocsSourceError
20	  >;
21	  readonly validateContent: () => Effect.Effect<
22	    DocsValidationResult,
23	    DocsSourceError
24	  >;
25	}
26	
27	export class DocsContentService extends Context.Service<
28	  DocsContentService,
29	  DocsContentServiceContract
30	>()("@taxkit/docs-content/DocsContentService") {}
 1	import type { FumadocsGeneratedCollectionAdapter } from "@taxkit/docs-fumadocs/live";
 2	import { makeFumadocsSourceLive } from "@taxkit/docs-fumadocs/live";
 3	import { Option } from "effect";
 4	
 5	import { source } from "./server.js";
 6	
 7	type GeneratedPage = ReturnType<typeof source.getPages>[number];
 8	
 9	const sourcePageRepresentation = async (page: GeneratedPage) => ({
10	  browserPath: page.path,
11	  frontmatter: {
12	    description: page.data.description,
13	    status: page.data.status,
14	    title: page.data.title,
15	  },
16	  markdown: await page.data.getText("processed"),
17	  slugs: page.slugs,
18	  sourcePath: `content/${page.path}`,
19	});
20	
21	const generatedCollectionAdapter: FumadocsGeneratedCollectionAdapter = {
22	  getPage: (slugs, locale) =>
23	    Option.fromUndefinedOr(
24	      source.getPage(globalThis.Array.from(slugs), locale)
25	    ).pipe(
26	      Option.match({
27	        onNone: () => Option.none<never>().pipe(Option.getOrUndefined),
28	        onSome: sourcePageRepresentation,
29	      })
30	    ),
31	  listPages: (locale) =>
32	    Promise.all(
33	      globalThis.Array.from(source.getPages(locale), sourcePageRepresentation)
34	    ),
35	};
36	
37	export const DocsGeneratedFumadocsSourceLive = makeFumadocsSourceLive(
38	  generatedCollectionAdapter
39	);

