   876	export const inspectDeploymentOwners = (
   877	  inventory: DeploymentJourneyInventory,
   878	  receipt: DeploymentAuthorityPreflightReceipt
   879	): readonly string[] => {
   880	  const findings: string[] = [];
   881	  const ids = Array.map(inventory.journeys, (journey) => journey.id);
   882	  if (
   883	    HashSet.size(HashSet.fromIterable(ids)) !== expectedJourneyIds.length ||
   884	    Array.some(expectedJourneyIds, (id) => !ids.includes(id))
   885	  ) {
   886	    findings.push(
   887	      "journey-inventory: retain exactly the four stable deployment journey IDs"
   888	    );
   889	  }
   890	  if (
   891	    Array.some(
   892	      inventory.journeys,
   893	      (journey) =>
   894	        journey.oracleClasses.length === 0 ||
   895	        journey.falseGreenOracles.length === 0 ||
   896	        !journey.receiptRoute.startsWith("docs/evidence/deployments/")
   897	    )
   898	  ) {
   899	    findings.push(
   900	      "journey-oracles: every journey needs dated evidence routing, proportional oracles and explicit false-green protection"
   901	    );
   902	  }
   903	  if (
   904	    receipt.candidate.status !== "not-trusted-pr-head" ||
   905	    receipt.candidate.pullRequestNumber !== null ||
   906	    receipt.state.mutationCount !== 0 ||
   907	    receipt.postcondition !== "stopped-before-state-or-provider-mutation"
   908	  ) {
   909	    findings.push(
   910	      "preflight-stop: an untrusted local-only candidate must stop before state initialization, plan or provider mutation"
   911	    );
   912	  }
   913	  if (
   914	    receipt.approval.approvedOperations.includes("preview-plan") &&
   915	    receipt.stop.operation !== "preview-plan"
   916	  ) {
   917	    findings.push(
   918	      "authority-stop: approval does not waive trusted-candidate identity"
   919	    );
   920	  }
   921	  const { evidenceDigest, ...evidenceProjection } = receipt;
   922	  const observedDigest = deploymentRecordDigest(evidenceProjection);
   923	  if (observedDigest !== evidenceDigest) {
   924	    findings.push(
   925	      "receipt-digest: evidenceDigest must bind the canonical receipt projection excluding itself"
   926	    );
   927	  }
   928	  return findings;
   929	};
