  1	import { defineRule, eslintCompatPlugin } from "@oxlint/plugins";
  2	import type { ESTree } from "@oxlint/plugins";
  3	import * as Array from "effect/Array";
  4	import * as Function from "effect/Function";
  5	import * as Option from "effect/Option";
  6	import * as Predicate from "effect/Predicate";
  7	import * as Schema from "effect/Schema";
  8	
  9	// Derived from DAW's owned rules at e47ecfb; this is the portable skill owner.
 10	const RuntimeOptions = Schema.Struct({ webSourceRoots: Schema.Array(Schema.String) });
 11	
 12	const noUncheckedIndex = defineRule({
 13	  meta: {
 14	    type: "problem",
 15	    schema: [],
 16	    messages: {
 17	      unchecked:
 18	        "Use Effect Array.get or Record.get and handle the Option result. Unchecked bracket lookups are forbidden.",
 19	    },
 20	  },
 21	  create(context) {
 22	    return {
 23	      MemberExpression(node) {
 24	        if (node.computed) {
 25	          context.report({ node, messageId: "unchecked" });
 26	        }
 27	      },
 28	    };
 29	  },
 30	});
 31	
 32	const noNativeAt = defineRule({
 33	  meta: {
 34	    type: "problem",
 35	    schema: [],
 36	    messages: {
 37	      nativeAt: "Use Effect Array.get and handle its Option result instead of native .at().",
 38	    },
 39	  },
 40	  create(context) {
 41	    return {
 42	      MemberExpression(node) {
 43	        if (node.property.type === "Identifier" && node.property.name === "at") {
 44	          context.report({ node, messageId: "nativeAt" });
 45	        }
 46	      },
 47	    };
 48	  },
 49	});
 50	
 51	const runtimeFileConvention = defineRule({
 52	  meta: {
 53	    type: "problem",
 54	    schema: [
 55	      {
 56	        type: "object",
 57	        properties: { webSourceRoots: { type: "array", items: { type: "string" } } },
 58	        required: ["webSourceRoots"],
 59	        additionalProperties: false,
 60	      },
 61	    ],
 62	    messages: {
 63	      runtimeFile:
 64	        "Name web Effect runtime modules runtime.server.ts or runtime.client.ts so TanStack checks the environment boundary.",
 65	    },
 66	  },
 67	  create(context) {
 68	    const filename = context.filename.replaceAll("\\", "/");
 69	    const roots = Function.pipe(
 70	      Array.head(context.options),
 71	      Option.flatMap(Schema.decodeUnknownOption(RuntimeOptions)),
 72	      Option.map((options) => options.webSourceRoots),
 73	      Option.getOrElse(() => ["apps/web/src"]),
 74	    );
 75	    return {
 76	      Program(node) {
 77	        if (
 78	          Array.some(roots, (root) =>
 79	            filename.includes(`/${root.replaceAll("\\", "/").replace(/\/$/u, "")}/`),
 80	          ) &&
 81	          /(?:^|\/)(?:runtime|[^/]+[.-]runtime)\.(?:ts|tsx)$/u.test(filename)
 82	        ) {
 83	          context.report({ node, messageId: "runtimeFile" });
 84	        }
 85	      },
 86	    };
 87	  },
 88	});
 89	
 90	// The Effect module, or the module export, that a local name or member path refers to.
 91	interface EffectReference {
 92	  readonly module: string;
 93	  readonly name: Option.Option<string>;
 94	}
 95	
 96	// A top-level value import of an Effect module or of one of its exports.
 97	interface EffectBinding {
 98	  readonly local: string;
 99	  readonly reference: EffectReference;
100	}
101	
102	// Effect's error factories are called without `new` and return a class to extend.
103	const effectErrorFactories: readonly (readonly [module: string, name: string])[] = [
104	  ["effect/Schema", "TaggedError"],
105	  ["effect/Schema", "Error"],
106	  ["effect/Data", "TaggedError"],
107	];
108	
109	// The name test used by unicorn/throw-new-error: Error, TypeError, URIError, CustomError and so on.
110	const errorName = /^(?:[A-Z][\da-z]*)*Error$/u;
111	
112	const exportedName = (name: ESTree.ModuleExportName): string => {
113	  if (name.type === "Literal") {
114	    return name.value;
115	  }
116	  return name.name;
117	};
118	
119	const isEffectSource = (source: string) => source === "effect" || source.startsWith("effect/");
120	
121	const moduleReference = (module: string): EffectReference => ({ module, name: Option.none() });
122	
123	// A member of the root `effect` module is itself a module, such as `effect/Schema`. A member of any other module is an export.
124	const memberReference = (
125	  reference: EffectReference,
126	  property: string,
127	): Option.Option<EffectReference> => {
128	  if (Option.isSome(reference.name)) {
129	    return Option.none();
130	  }
131	  if (reference.module === "effect") {
132	    return Option.some(moduleReference(`effect/${property}`));
133	  }
134	  return Option.some({ module: reference.module, name: Option.some(property) });
135	};
136	
137	const specifierBinding = (
138	  source: string,
139	  specifier: ESTree.ImportDeclarationSpecifier,
140	): Option.Option<EffectBinding> => {
141	  if (specifier.type === "ImportDefaultSpecifier") {
142	    return Option.none();
143	  }
144	  const local = specifier.local.name;
145	  if (specifier.type === "ImportNamespaceSpecifier") {
146	    return Option.some({ local, reference: moduleReference(source) });
147	  }
148	  if (specifier.importKind === "type") {
149	    return Option.none();
150	  }
151	  const module = moduleReference(source);
152	  const imported = exportedName(specifier.imported);
153	  return Function.pipe(
154	    memberReference(module, imported),
155	    Option.map((reference) => ({ local, reference })),
156	  );
157	};
158	
159	const effectBindings = (program: ESTree.Program): readonly EffectBinding[] =>
160	  Function.pipe(
161	    program.body,
162	    Array.flatMap((statement) => {
163	      if (
164	        statement.type !== "ImportDeclaration" ||
165	        statement.importKind === "type" ||
166	        !isEffectSource(statement.source.value)
167	      ) {
168	        return [];
169	      }
170	      return Function.pipe(
171	        statement.specifiers,
172	        Array.flatMap((specifier) =>
173	          Option.toArray(specifierBinding(statement.source.value, specifier)),
174	        ),
175	      );
176	    }),
177	  );
178	
179	// Follows an identifier or a chain of static member reads, such as `Effect.Schema.TaggedError`, back to its Effect import.
180	const resolveReference = (
181	  bindings: readonly EffectBinding[],
182	  expression: ESTree.Expression,
183	): Option.Option<EffectReference> => {
184	  if (expression.type === "Identifier") {
185	    return Function.pipe(
186	      bindings,
187	      Array.findFirst((binding) => binding.local === expression.name),
188	      Option.map((binding) => binding.reference),
189	    );
190	  }
191	  if (
192	    expression.type !== "MemberExpression" ||
193	    expression.computed ||
194	    expression.property.type !== "Identifier"
195	  ) {
196	    return Option.none();
197	  }
198	  const property = expression.property.name;
199	  return Function.pipe(
200	    resolveReference(bindings, expression.object),
201	    Option.flatMap((reference) => memberReference(reference, property)),
202	  );
203	};
204	
205	const isExport = (reference: EffectReference, module: string, name: string) =>
206	  reference.module === module && Option.contains(reference.name, name);
207	
208	const selfTypeName = (type: ESTree.TSType): Option.Option<string> => {
209	  if (type.type === "TSTypeReference" && type.typeName.type === "Identifier") {
210	    return Option.some(type.typeName.name);
211	  }
212	  return Option.none();
213	};
214	
215	const literalTag = (argument: ESTree.Argument): Option.Option<string> => {
216	  if (argument.type === "Literal") {
217	    return Option.liftPredicate(argument.value, Predicate.isString);
218	  }
219	  return Option.none();
220	};
221	
222	const missing = (name: Option.Option<string>) => Option.getOrElse(name, () => "<missing>");
223	
224	// Match the installed RC factory through its actual import.
225	const taggedErrorName = defineRule({
226	  meta: {
227	    type: "problem",
228	    schema: [],
229	    messages: {
230	      mismatch:
231	        "Give a Schema.TaggedError class, its self type and its literal tag the same name. Found class {{className}}, self type {{selfTypeName}} and tag {{tagName}}.",
232	    },
233	  },
234	  create(context) {
235	    const check = (node: ESTree.Class) => {
236	      const { superClass } = node;
237	      if (superClass?.type !== "CallExpression") {
238	        return;
239	      }
240	      const factory = superClass.callee;
241	      if (factory.type !== "CallExpression") {
242	        return;
243	      }
244	      const bindings = effectBindings(context.sourceCode.ast);
245	      const isSchemaTaggedError = Function.pipe(
246	        resolveReference(bindings, factory.callee),
247	        Option.exists((reference) => isExport(reference, "effect/Schema", "TaggedError")),
248	      );
249	      if (!isSchemaTaggedError) {
250	        return;
251	      }
252	      const className = Function.pipe(
253	        Option.fromNullishOr(node.id),
254	        Option.map((id) => id.name),
255	      );
256	      const selfType = Function.pipe(
257	        Option.fromNullishOr(factory.typeArguments),
258	        Option.flatMap((typeArguments) => Array.head(typeArguments.params)),
259	        Option.flatMap(selfTypeName),
260	      );
261	      const tag = Function.pipe(Array.head(superClass.arguments), Option.flatMap(literalTag));
262	      const agrees = Function.pipe(
263	        Option.all([className, selfType, tag]),
264	        Option.exists(([name, self, literal]) => name === self && name === literal),
265	      );
266	      if (!agrees) {
267	        context.report({
268	          node,
269	          messageId: "mismatch",
270	          data: {
271	            className: missing(className),
272	            selfTypeName: missing(selfType),
273	            tagName: missing(tag),
274	          },
275	        });
276	      }
277	    };
278	    return { ClassDeclaration: check, ClassExpression: check };
279	  },
280	});
281	
282	const calleeName = (callee: ESTree.Expression): Option.Option<string> => {
283	  if (callee.type === "Identifier") {
284	    return Option.some(callee.name);
285	  }
286	  if (
287	    callee.type === "MemberExpression" &&
288	    !callee.computed &&
289	    callee.property.type === "Identifier"
290	  ) {
291	    return Option.some(callee.property.name);
292	  }
293	  return Option.none();
294	};
295	
296	const isEffectErrorFactory = (reference: EffectReference) =>
297	  Function.pipe(
298	    effectErrorFactories,
299	    Array.some(([module, name]) => isExport(reference, module, name)),
300	  );
301	
