115	For the qualified Effect v4 RC API, use the two-argument `Layer.effect`. Check
116	installed types before copying this into a different version. `Service.of`
117	checks the implementation against the service contract; it does not run it.
118	
119	```ts
120	export const AccountsLive = Layer.effect(
121	  Accounts,
122	  Effect.gen(function* () {
123	    const store = yield* AccountsStore;
124	    return Accounts.of({
125	      load: Effect.fn("Accounts.load")((id: AccountId) => store.load(id)),
126	      create: Effect.fn("Accounts.create")((input: CreateAccount) => store.create(input)),
127	    });
128	  }),
129	);
130	```
