477	const noRuntimeOutsideBoundary = defineRule({
478	  meta: {
479	    type: "problem",
480	    schema: boundarySchema,
481	    messages: {
482	      runtime:
483	        "Execute Effect only in an explicitly approved application or command runtime. Tests use @effect/vitest.",
484	    },
485	  },
486	  create(context) {
487	    const allowed = isBoundary(context.filename, context.cwd, context.options);
488	    return {
489	      CallExpression(node) {
490	        if (allowed) return;
491	        const name = calleeName(node.callee);
492	        const imported = resolveReference(effectBindings(context.sourceCode.ast), node.callee);
493	        const operation = Option.flatMap(imported, (reference) =>
494	          reference.module === "effect/Effect" ? reference.name : Option.none(),
495	        );
496	        const runs = Option.exists(
497	          Option.orElse(operation, () => name),
498	          (value) =>
499	            /^(?:runPromise(?:Exit)?|runSync(?:Exit)?|runFork|runCallback|runMain)$/u.test(value),
500	        );
501	        const creates = Option.exists(
502	          resolveReference(effectBindings(context.sourceCode.ast), node.callee),
503	          (reference) => isExport(reference, "effect/ManagedRuntime", "make"),
504	        );
505	        if (runs || creates) context.report({ node, messageId: "runtime" });
506	      },
507	    };
508	  },
509	});
510	
511	// Recognises direct host spellings, not arbitrary local aliases or shadowed names.
512	const hostPath = (expression: ESTree.Expression): Option.Option<string> => {
513	  if (expression.type === "Identifier") return Option.some(expression.name);
514	  if (expression.type === "MetaProperty")
515	    return Option.some(`${expression.meta.name}.${expression.property.name}`);
516	  if (expression.type !== "MemberExpression") return Option.none();
517	  const property =
518	    expression.property.type === "Identifier" && !expression.computed
519	      ? Option.some(expression.property.name)
520	      : expression.property.type === "Literal"
521	        ? Option.liftPredicate(expression.property.value, Predicate.isString)
522	        : Option.none();
523	  return Function.pipe(
524	    Option.all([hostPath(expression.object), property]),
525	    Option.map(([object, name]) => `${object}.${name}`),
526	  );
527	};
528	
529	const noNativeWork = defineRule({
530	  meta: {
531	    type: "problem",
532	    schema: [],
533	    messages: {
534	      nativeWork:
535	        "Use typed Effect failures, Config, Clock and Random instead of throws, try/catch or ambient host work.",
536	    },
537	  },
538	  create(context) {
539	    const report = (node: ESTree.Node) => context.report({ node, messageId: "nativeWork" });
540	    const clock = (expression: ESTree.Expression) =>
541	      Option.exists(hostPath(expression), (path) =>
542	        /^(?:(?:globalThis|window)\.)?Date$/u.test(path),
543	      );
544	    return {
545	      ThrowStatement: report,
546	      TryStatement: report,
547	      NewExpression(node) {
548	        // Explicit timestamp conversion is pure; acquiring the current time is not.
549	        if (node.arguments.length === 0 && clock(node.callee)) report(node);
550	      },
551	      CallExpression(node) {
552	        // Calling Date as a function reads the clock even when arguments are supplied.
553	        if (clock(node.callee)) report(node);
554	      },
555	      MemberExpression(node) {
556	        if (
557	          Option.exists(
558	            hostPath(node),
559	            (path) =>
560	              /^(?:(?:globalThis|window)\.)?(?:process\.env|Bun\.env|Date\.now|Math\.random|crypto\.(?:randomUUID|getRandomValues))$/u.test(
561	                path,
562	              ) || path === "import.meta.env",
563	          )
564	        )
565	          report(node);
566	      },
567	    };
568	  },
569	});
570	
571	export default eslintCompatPlugin({
572	  meta: { name: "strict-effect" },
573	  rules: {
574	    "no-unchecked-index": noUncheckedIndex,
575	    "no-native-at": noNativeAt,
576	    "runtime-file-convention": runtimeFileConvention,
577	    "tagged-error-name": taggedErrorName,
578	    "error-constructor-new": errorConstructorNew,
579	    "no-promise-workflow": noPromiseWorkflow,
580	    "no-unsafe-option-unwrap": noUnsafeOptionUnwrap,
581	    "no-unchecked-json": noUncheckedJson,
582	    "no-runtime-outside-boundary": noRuntimeOutsideBoundary,
583	    "no-native-work": noNativeWork,
584	  },
585	});

