 90	// The Effect module, or the module export, that a local name or member path refers to.
 91	interface EffectReference {
 92	  readonly module: string;
 93	  readonly name: Option.Option<string>;
 94	}
 95	
 96	// A top-level value import of an Effect module or of one of its exports.
 97	interface EffectBinding {
 98	  readonly local: string;
 99	  readonly reference: EffectReference;
100	}
101	
102	// Effect's error factories are called without `new` and return a class to extend.
103	const effectErrorFactories: readonly (readonly [module: string, name: string])[] = [
104	  ["effect/Schema", "TaggedError"],
105	  ["effect/Schema", "Error"],
106	  ["effect/Data", "TaggedError"],
107	];
108	
109	// The name test used by unicorn/throw-new-error: Error, TypeError, URIError, CustomError and so on.
110	const errorName = /^(?:[A-Z][\da-z]*)*Error$/u;
111	
112	const exportedName = (name: ESTree.ModuleExportName): string => {
113	  if (name.type === "Literal") {
114	    return name.value;
115	  }
116	  return name.name;
117	};
118	
119	const isEffectSource = (source: string) =>
120	  source === "effect" ||
121	  source.startsWith("effect/") ||
122	  source === "alchemy" ||
123	  source.startsWith("alchemy/");
124	
125	const moduleReference = (module: string): EffectReference => ({ module, name: Option.none() });
126	
127	// A member of the root `effect` module is itself a module, such as `effect/Schema`. A member of any other module is an export.
128	const memberReference = (
129	  reference: EffectReference,
130	  property: string,
131	): Option.Option<EffectReference> => {
132	  if (Option.isSome(reference.name)) {
133	    return Option.none();
134	  }
135	  if (reference.module === "effect" || reference.module === "alchemy") {
136	    return Option.some(moduleReference(`${reference.module}/${property}`));
137	  }
138	  return Option.some({ module: reference.module, name: Option.some(property) });
139	};
140	
141	const specifierBinding = (
142	  source: string,
143	  specifier: ESTree.ImportDeclarationSpecifier,
144	): Option.Option<EffectBinding> => {
145	  if (specifier.type === "ImportDefaultSpecifier") {
146	    return Option.none();
147	  }
148	  const local = specifier.local.name;
149	  if (specifier.type === "ImportNamespaceSpecifier") {
150	    return Option.some({ local, reference: moduleReference(source) });
151	  }
152	  if (specifier.importKind === "type") {
153	    return Option.none();
154	  }
155	  const module = moduleReference(source);
156	  const imported = exportedName(specifier.imported);
157	  return Function.pipe(
158	    memberReference(module, imported),
159	    Option.map((reference) => ({ local, reference })),
160	  );
161	};
162	
163	const effectBindings = (program: ESTree.Program): readonly EffectBinding[] =>
164	  Function.pipe(
165	    program.body,
166	    Array.flatMap((statement) => {
167	      if (
168	        statement.type !== "ImportDeclaration" ||
169	        statement.importKind === "type" ||
170	        !isEffectSource(statement.source.value)
171	      ) {
172	        return [];
173	      }
174	      return Function.pipe(
175	        statement.specifiers,
176	        Array.flatMap((specifier) =>
177	          Option.toArray(specifierBinding(statement.source.value, specifier)),
178	        ),
179	      );
180	    }),
181	  );
182	
183	// Follows an identifier or a chain of static member reads, such as `Effect.Schema.TaggedError`, back to its Effect import.
184	const resolveReference = (
185	  bindings: readonly EffectBinding[],
186	  expression: ESTree.Expression,
187	): Option.Option<EffectReference> => {
188	  if (expression.type === "Identifier") {
189	    return Function.pipe(
190	      bindings,
191	      Array.findFirst((binding) => binding.local === expression.name),
192	      Option.map((binding) => binding.reference),
193	    );
194	  }
195	  if (
196	    expression.type !== "MemberExpression" ||
197	    expression.computed ||
198	    expression.property.type !== "Identifier"
199	  ) {
200	    return Option.none();
201	  }
202	  const property = expression.property.name;
203	  return Function.pipe(
204	    resolveReference(bindings, expression.object),
205	    Option.flatMap((reference) => memberReference(reference, property)),
206	  );

